import { httpAjax } from './httpAjax/index.js'

const audio = new Audio();
const mainPromise = new Promise((resolve, reject) => {
    resolve(httpAjax('GET', '../../stations.json', 'json'))
});

mainPromise
    .then(data => {
        console.log(typeof data);
        return data
    })
    .then(stations => {
        checkStations(stations);
    })
    .finally()
    .catch()


async function checkStations(stations) {
    for (const station of stations.slice(0, 100)) {
        try {
            const response = await fetch(station.url, {
                headers: { 'Icy-MetaData': '1' },
                signal: AbortSignal.timeout(5000)
            });

            console.log(
                station.name,
                'HTTP:', response.status,
                'icy-metaint:', response.headers.get('icy-metaint')
            );

            await response.body?.cancel();
        } catch (error) {
            console.log(station.name, 'Ошибка:', error.message);
        }
    }
}